/**
 * ⑪.2 DeepSeek MAIN-world content-script adapter.
 *
 * Flow (mirrors chromeclaw's content-fetch-deepseek.ts):
 *  1. Read bearer token from localStorage['userToken'] (with fallbacks)
 *  2. fetch POST /api/v0/chat_session/create → get chat_session_id
 *  3. fetch POST /api/v0/chat/create_pow_challenge → get PoW challenge
 *  4. Solve PoW (sha256 path) — DeepSeekHashV1 will surface as a clear
 *     "unsupported algorithm" error so the bridge can ask the user to retry
 *     after a page reload (V1 needs WASM solver which we add in a follow-up).
 *  5. fetch POST /api/v0/chat/completion with x-ds-pow-response header →
 *     stream SSE chunks back via window.postMessage.
 *
 * Self-contained — chrome.scripting.executeScript serializes only the
 * function body, no module-scope imports survive.
 */
import type { ContentFetchRequest } from './web-provider-content-fetch-main';

/**
 * ⑨.5: DeepSeek R1 "thinking mode" emits a chain-of-thought preamble
 * before the real answer. The preamble typically ends with a literal
 * "FINISHED" sentinel followed by the actual response. To keep the
 * sidepanel clean (the user only wants the answer, not the CoT), we
 * buffer every chunk until we see the boundary, then emit only the
 * post-boundary content.
 *
 * Exported for unit testing in `web-provider-content-fetch-deepseek.test.ts`.
 * The actual integration lives in `deepseekMainWorldFetch` below, which
 * feeds parsed JSON SSE payloads into this function and forwards the
 * resulting events to the bridge.
 */
export interface DeepSeekRawChunk {
  v: string;
}

export interface DeepSeekFilteredEvent {
  type: 'text' | 'finish';
  text?: string;
}

/**
 * Find the byte offset of the FINISHED sentinel in a chunk string.
 * Returns -1 if not found. The sentinel may appear at any position;
 * trailing whitespace and a single trailing newline are tolerated.
 */
export function findFinishedOffset(chunk: string): number {
  const idx = chunk.indexOf('FINISHED');
  if (idx < 0) return -1;
  return idx;
}

/**
 * Filter DeepSeek's stream of SSE JSON payloads into a list of
 * bridge events. The returned events are:
 *   - `{ type: 'text', text }` concatenating all chunks after the
 *     FINISHED marker (or all chunks if no marker is found —
 *     the model is in non-thinking mode)
 *   - `{ type: 'finish' }` always emitted last
 *
 * Any chunk emitted before the FINISHED marker is dropped — it is
 * assumed to be CoT and should not reach the sidepanel.
 */
export function filterDeepSeekStream(
  rawChunks: DeepSeekRawChunk[],
): DeepSeekFilteredEvent[] {
  const events: DeepSeekFilteredEvent[] = [];
  let seenFinished = false;
  let answerText = '';

  for (const chunk of rawChunks) {
    if (typeof chunk.v !== 'string' || chunk.v.length === 0) continue;

    if (seenFinished) {
      answerText += chunk.v;
      continue;
    }

    const offset = findFinishedOffset(chunk.v);
    if (offset >= 0) {
      // The text after the marker is part of the answer.
      const after = chunk.v
        .slice(offset + 'FINISHED'.length)
        .replace(/^\s*\n?/, '');
      answerText += after;
      seenFinished = true;
    }
    // else: no marker yet — chunk is still CoT, drop it.
  }

  // If we never saw FINISHED, fall back to treating every chunk as
  // the answer (non-thinking mode). Otherwise the user would see an
  // empty sidepanel for any model that doesn't emit the marker.
  if (!seenFinished) {
    answerText = rawChunks
      .filter((c) => typeof c.v === 'string' && c.v.length > 0)
      .map((c) => c.v)
      .join('');
  }

  if (answerText.length > 0) {
    events.push({ type: 'text', text: answerText });
  }
  events.push({ type: 'finish' });
  return events;
}

/** Re-export a stable type for consumers of the stream result. */
export type deepSeekStreamResult = DeepSeekFilteredEvent;

/**
 * ⑬: Max wall-clock for the entire adapter call. If the user can reach
 * DeepSeek's HTML but not the streaming endpoint (e.g. `hif-dliq.deepseek.com`
 * DNS-blocked in their network), `fetch` may eventually fail or the
 * reader can stall. We cap the call at this duration so the sidepanel
 * spinner never spins forever; after 90s we surface a clear error.
 */
const ADAPTER_TIMEOUT_MS = 90_000;

export const deepseekMainWorldFetch = async (request: ContentFetchRequest): Promise<void> => {
  const { requestId, init } = request;
  const origin = window.location.origin;

  // ⑫ FIX: cross-world messaging via document CustomEvent
  // (window.postMessage doesn't cross the MAIN↔ISOLATED world boundary)
  // ⑫ providerId must be in the event detail — the ISOLATED bridge
  // filters by data.providerId === installed-providerId, and drops
  // anything that doesn't match. We capture it from the request so
  // every postToBridge call automatically includes it.
  const postToBridge = (data: Record<string, unknown>, _origin?: string): void => {
    document.dispatchEvent(new CustomEvent('ceb-web-provider-message', {
      detail: { ...data, providerId: request.providerId },
    }));
  };

  // ⑬: Adapter-level wall-clock timeout. Race the body against a
  // timer so a hung fetch / stalled reader can't pin the sidepanel
  // in a loading state. The body is wrapped in an inner async so
  // EVERY exit path (early returns, exceptions, normal completion)
  // clears the timer exactly once via finally. The outer Promise.race
  // guarantees a timely resolution; whichever wins decides the
  // error message.
  let timeoutHandle: ReturnType<typeof setTimeout> | null = null;
  const work = (async () => {
    await runDeepseekBody(request, requestId, init, origin, postToBridge);
  })();
  const timeout = new Promise<never>((_, reject) => {
    timeoutHandle = setTimeout(
      () =>
        reject(
          new Error(
            `DeepSeek adapter timed out after ${Math.round(
              ADAPTER_TIMEOUT_MS / 1000,
            )}s. The streaming endpoint (likely hif-dliq.deepseek.com) may be unreachable from this network.`,
          ),
        ),
      ADAPTER_TIMEOUT_MS,
    );
  });

  try {
    await Promise.race([work, timeout]);
  } catch (err) {
    postToBridge(
      {
        type: 'WEB_LLM_ERROR',
        requestId,
        error: err instanceof Error ? err.message : String(err),
      },
      origin,
    );
    postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
  } finally {
    if (timeoutHandle !== null) clearTimeout(timeoutHandle);
  }
};

/**
 * Inner body of the DeepSeek adapter. Pulled out so the outer
 * `deepseekMainWorldFetch` can race it against a timeout without
 * littering every early-return with `clearTimeout`. Returns when
 * the stream has been fully drained and DONE has been emitted.
 */
const runDeepseekBody = async (
  request: ContentFetchRequest,
  requestId: string,
  init: RequestInit,
  origin: string,
  postToBridge: (data: Record<string, unknown>, origin?: string) => void,
): Promise<void> => {

  // ── Helper: Solve DeepSeekHashV1 PoW challenge via embedded WASM ──
  // SHA3-based hash compiled to WASM (from chromeclaw reference impl).
  // The WASM module exports wasm_solve(retptr, ptrC, lenC, ptrP, lenP, dificultad)
  // which writes {status: i32, answer: f64} at retptr.
  // WASM module is 26612B, base64 is 35484 chars.
  const solveDeepSeekHashV1 = async (powCh: PowChallenge): Promise<number> => {
    const WASM_B64 = '';
    const binaryStr = atob(WASM_B64);
    const wasmBytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++) {
      wasmBytes[i] = binaryStr.charCodeAt(i);
    }
    const { instance } = await WebAssembly.instantiate(wasmBytes.buffer, { wbg: {} });
    const exports = instance.exports as Record<string, unknown>;
    const memory = exports.memory as WebAssembly.Memory;
    const alloc = exports.__wbindgen_export_0 as (a: number, b: number) => number;
    const addToStack = exports.__wbindgen_add_to_stack_pointer as (a: number) => number;
    const wasmSolve = exports.wasm_solve as (
      retptr: number, ptrC: number, lenC: number, ptrP: number, lenP: number, dificultad: number
    ) => void;
    const prefix = `${powCh.salt}_${powCh.expire_at ?? 0}_`;
    const challengeStr = powCh.challenge;
    const encodeString = (str: string, ptr: number): number => {
      const buf = new TextEncoder().encode(str);
      new Uint8Array(memory.buffer).set(buf, ptr);
      return buf.length;
    };
    // Allocate BOTH buffers first, then write data (avoids detached buffer bug after memory.grow)
    const challengeBuf = new TextEncoder().encode(challengeStr);
    const prefixBuf = new TextEncoder().encode(prefix);
    const ptrC = alloc(challengeBuf.length, 1);
    const ptrP = alloc(prefixBuf.length, 1);
    const lenC = encodeString(challengeStr, ptrC);
    const lenP = encodeString(prefix, ptrP);
    const retptr = addToStack(-16);
    wasmSolve(retptr, ptrC, lenC, ptrP, lenP, powCh.difficulty);
    const view = new DataView(memory.buffer);
    const status = view.getInt32(retptr, true);
    const answer = view.getFloat64(retptr + 8, true);
    addToStack(16);
    if (status === 0) return -1;
    return answer;
  };
  // ── Step 1: Bearer token from localStorage ──
  const extractBearerToken = async (): Promise<string> => {
    let bearer = '';
    try {
      const raw = localStorage.getItem('userToken');
      if (raw) {
        try {
          const parsed = JSON.parse(raw);
          if (typeof parsed === 'string') bearer = parsed;
          else if (typeof parsed === 'object' && parsed !== null) {
            bearer = parsed.token ?? parsed.value ?? parsed.access_token ?? parsed.jwt ?? '';
          }
        } catch {
          bearer = raw;
        }
      }
    } catch {
      /* ignore */
    }
    if (!bearer) {
      try {
        for (const key of ['token', 'ds_token', 'auth_token', 'access_token', 'jwt']) {
          const val = localStorage.getItem(key);
          if (val && val.length > 10) {
            try {
              const parsed = JSON.parse(val);
              if (typeof parsed === 'string' && parsed.length > 10) bearer = parsed;
              else if (typeof parsed === 'object' && parsed !== null) {
                bearer = parsed.token ?? parsed.value ?? '';
              }
            } catch {
              bearer = val;
            }
            if (bearer) break;
          }
        }
      } catch {
        /* ignore */
      }
    }
    if (!bearer) {
      try {
        for (let i = 0; i < localStorage.length; i++) {
          const key = localStorage.key(i);
          if (!key || key === 'userToken') continue;
          const lk = key.toLowerCase();
          if (lk.includes('token') || lk.includes('auth') || lk.includes('jwt') || lk.includes('bearer')) {
            const val = localStorage.getItem(key);
            if (val && val.length > 10) {
              try {
                const parsed = JSON.parse(val);
                if (typeof parsed === 'string' && parsed.length > 10) bearer = parsed;
                else if (typeof parsed === 'object' && parsed !== null) {
                  bearer = parsed.token ?? parsed.value ?? '';
                }
              } catch {
                bearer = val;
              }
              if (bearer) break;
            }
          }
        }
      } catch {
        /* ignore */
      }
    }
    return bearer;
  };

  // ── Step 2: Parse prompt + chat id from stub body ──
  let dsPrompt = '';
  let existingChatId = '';
  try {
    const bodyObj = JSON.parse(typeof init.body === 'string' ? init.body : '{}') as Record<
      string,
      string
    >;
    dsPrompt = bodyObj.prompt ?? '';
    existingChatId = bodyObj.chatId ?? '';
  } catch {
    /* defaults */
  }

  const bearer = await extractBearerToken();
  if (!bearer) {
    let utPreview = '(none)';
    try {
      const ut = localStorage.getItem('userToken');
      if (ut) utPreview = `len=${ut.length}`;
    } catch {
      /* ignore */
    }
    postToBridge(
      {
        type: 'WEB_LLM_ERROR',
        requestId,
        error: `No auth token found for DeepSeek. userToken: ${utPreview}. Please visit ${origin}, log in, then reconnect via Settings → Web Providers.`,
      },
      origin,
    );
    return;
  }

  // ── Step 3: Extract version from page globals (best-effort) ──
  let clientVersion = '1.7.0';
  let appVersion = '20241129.1';
  try {
    const meta = document.querySelector('meta[name="version"]');
    if (meta?.getAttribute('content')) {
      appVersion = meta.getAttribute('content')!;
    }
    const nextData = (window as unknown as Record<string, unknown>).__NEXT_DATA__ as
      | { buildId?: string }
      | undefined;
    if (nextData?.buildId) {
      appVersion = nextData.buildId;
    }
    const w = window as unknown as Record<string, unknown>;
    const appVer = w.__APP_VERSION__ as string | undefined;
    if (appVer) appVersion = appVer;
    const clientVer = w.__CLIENT_VERSION__ as string | undefined;
    if (clientVer) clientVersion = clientVer;
  } catch {
    /* use defaults */
  }

  const dsHeaders: Record<string, string> = {
    'Content-Type': 'application/json',
    Accept: '*/*',
    Referer: `${origin}/`,
    Origin: origin,
    'x-client-platform': 'web',
    'x-client-version': clientVersion,
    'x-app-version': appVersion,
    Authorization: `Bearer ${bearer}`,
  };

  // ── Step 4: Create chat session if needed ──
  let chatSessionId = existingChatId;
  if (!chatSessionId) {
    try {
      const createRes = await fetch(`${origin}/api/v0/chat_session/create`, {
        method: 'POST',
        headers: dsHeaders,
        credentials: 'include',
        body: JSON.stringify({}),
      });
      if (!createRes.ok) {
        const authHint =
          createRes.status === 401 || createRes.status === 403
            ? ' Please visit the page to verify your account, then log out and log back in via Settings → Web Providers.'
            : '';
        postToBridge(
          {
            type: 'WEB_LLM_ERROR',
            requestId,
            error: `Chat session creation failed: HTTP ${createRes.status}${authHint}`,
          },
          origin,
        );
        return;
      }
      const sessionData = (await createRes.json()) as Record<string, unknown>;
      if (sessionData.code !== undefined && sessionData.code !== 0) {
        postToBridge(
          {
            type: 'WEB_LLM_ERROR',
            requestId,
            error: `Chat session error: code=${sessionData.code}, msg=${sessionData.msg ?? 'unknown'}`,
          },
          origin,
        );
        return;
      }
      const bizOuter = sessionData.data as Record<string, unknown> | undefined;
      const biz = (bizOuter?.biz_data ?? bizOuter) as Record<string, string> | undefined;
      chatSessionId = biz?.id ?? biz?.chat_session_id ?? '';
    } catch (err) {
      postToBridge(
        { type: 'WEB_LLM_ERROR', requestId, error: `Chat session error: ${String(err)}` },
        origin,
      );
      return;
    }
  }

  // ── Step 5: PoW challenge ──
  type PowChallenge = {
    algorithm: string;
    challenge: string;
    difficulty: number;
    salt: string;
    signature: string;
    expire_at?: number;
  };

  let powChallenge: PowChallenge;
  try {
    const powRes = await fetch(`${origin}/api/v0/chat/create_pow_challenge`, {
      method: 'POST',
      headers: dsHeaders,
      credentials: 'include',
      body: JSON.stringify({ target_path: '/api/v0/chat/completion' }),
    });
    if (!powRes.ok) {
      postToBridge(
        {
          type: 'WEB_LLM_ERROR',
          requestId,
          error: `PoW request failed: HTTP ${powRes.status}`,
        },
        origin,
      );
      return;
    }
    const powData = (await powRes.json()) as Record<string, unknown>;
    if (powData.code !== undefined && powData.code !== 0) {
      postToBridge(
        {
          type: 'WEB_LLM_ERROR',
          requestId,
          error: `PoW API error: code=${powData.code}, msg=${powData.msg ?? 'unknown'}`,
        },
        origin,
      );
      return;
    }
    const dataObj = powData.data as Record<string, unknown> | undefined;
    const biz = dataObj?.biz_data as Record<string, unknown> | undefined;
    let raw: unknown = (biz as Record<string, unknown> | undefined)?.challenge ?? dataObj?.challenge ?? powData.challenge;
    if ((!raw || typeof raw !== 'object') && (biz as Record<string, unknown> | undefined)?.algorithm && (biz as Record<string, unknown> | undefined)?.salt) {
      raw = biz;
    }
    if (!raw || typeof raw !== 'object') {
      postToBridge(
        {
          type: 'WEB_LLM_ERROR',
          requestId,
          error: `PoW challenge missing in response`,
        },
        origin,
      );
      return;
    }
    const c = raw as Record<string, unknown>;
    if (
      typeof c.algorithm !== 'string' ||
      typeof c.challenge !== 'string' ||
      typeof c.difficulty !== 'number' ||
      typeof c.salt !== 'string' ||
      typeof c.signature !== 'string'
    ) {
      postToBridge(
        { type: 'WEB_LLM_ERROR', requestId, error: `PoW challenge missing required fields` },
        origin,
      );
      return;
    }
    powChallenge = c as unknown as PowChallenge;
  } catch (err) {
    postToBridge(
      { type: 'WEB_LLM_ERROR', requestId, error: `PoW challenge error: ${String(err)}` },
      origin,
    );
    return;
  }

  // ── Step 6: Solve PoW ──
  const solveSha256Pow = async (
    salt: string,
    challenge: string,
    difficulty: number,
  ): Promise<number> => {
    const targetDifficulty = difficulty > 64 ? Math.floor(Math.log2(difficulty)) : difficulty;
    const encoder = new TextEncoder();
    for (let nonce = 0; nonce < 1_000_000; nonce++) {
      const hashBuf = await crypto.subtle.digest(
        'SHA-256',
        encoder.encode(salt + challenge + nonce),
      );
      const hashArr = new Uint8Array(hashBuf);
      const hex = Array.from(hashArr, b => b.toString(16).padStart(2, '0')).join('');
      let zeroBits = 0;
      for (const ch of hex) {
        const val = parseInt(ch, 16);
        if (val === 0) zeroBits += 4;
        else {
          zeroBits += Math.clz32(val) - 28;
          break;
        }
      }
      if (zeroBits >= targetDifficulty) return nonce;
    }
    return -1;
  };

  let powAnswer: number;
  if (powChallenge.algorithm === 'sha256') {
    powAnswer = await solveSha256Pow(
      powChallenge.salt,
      powChallenge.challenge,
      powChallenge.difficulty,
    );



  } else if (powChallenge.algorithm === 'DeepSeekHashV1') {
    // ⑫: Solve via embedded WASM (SHA3-based, 26KB inline).
    // Solve takes 2-15s depending on difficulty; user sees a brief pause.
    powAnswer = await solveDeepSeekHashV1(powChallenge);
    if (powAnswer === -1) {
      postToBridge(
        {
          type: 'WEB_LLM_ERROR',
          requestId,
          error: 'DeepSeekHashV1 PoW solve failed (no nonce found within WASM attempt window). Please retry.',
        },
        origin,
      );
      return;
    }
  } else {
    postToBridge(
      {
        type: 'WEB_LLM_ERROR',
        requestId,
        error: `Unsupported PoW algorithm: ${powChallenge.algorithm}. Only sha256 and DeepSeekHashV1 are supported.`,
      },
      origin,
    );
    return;
  }

  if (powAnswer < 0) {
    postToBridge(
      {
        type: 'WEB_LLM_ERROR',
        requestId,
        error: `PoW solve failed (${powChallenge.algorithm})`,
      },
      origin,
    );
    return;
  }

  const powResponse = btoa(
    JSON.stringify({
      ...powChallenge,
      answer: powAnswer,
      target_path: '/api/v0/chat/completion',
    }),
  );

  // ── Step 7: Send completion request (SSE) ──
  const dsResponse = await fetch(`${origin}/api/v0/chat/completion`, {
    method: 'POST',
    headers: {
      ...dsHeaders,
      'x-ds-pow-response': powResponse,
    },
    credentials: 'include',
    body: JSON.stringify({
      chat_session_id: chatSessionId,
      parent_message_id: null,
      prompt: dsPrompt,
      ref_file_ids: [],
      thinking_enabled: true,
      search_enabled: false,
      preempt: false,
    }),
  });

  if (!dsResponse.ok) {
    postToBridge(
      {
        type: 'WEB_LLM_ERROR',
        requestId,
        error: `HTTP ${dsResponse.status}: ${dsResponse.statusText}`,
      },
      origin,
    );
    return;
  }

  const dsReader = dsResponse.body?.getReader();
  if (!dsReader) {
    postToBridge(
      { type: 'WEB_LLM_ERROR', requestId, error: 'No response body from DeepSeek' },
      origin,
    );
    return;
  }

  if (chatSessionId) {
    // ⑨.2: tell the SW to persist this session id so the next turn's
    // buildContentFetchRequest can echo it back as `chatId` in init.body.
    // ⑫: don't leak the raw `data: {deepseek:chat_session_id}` envelope
    // to the sidepanel — that was a UX bug fixed in the same commit family.
    // Fire-and-forget; SW listener will call setConversation() and any
    // Dexie failure is just a console.warn there.
    postToBridge(
      {
        type: 'WEB_LLM_CONVERSATION_UPDATE',
        requestId,
        modelId: request.modelId,
        conversationId: chatSessionId,
      },
      origin,
    );
  }

  const decoder = new TextDecoder();
  let buffer = '';
  // ⑨.5: we want to hide DeepSeek's chain-of-thought preamble and
  // only emit the post-FINISHED content. Two streaming goals:
  //   (a) post-FINISHED text should arrive incrementally so the
  //       sidepanel renders it chunk-by-chunk (better UX than a
  //       single all-at-once reveal);
  //   (b) the no-FINISHED case (non-thinking mode) should still
  //       show every chunk in order.
  // Strategy: track a flag + accumulate the post-FINISHED text
  // across read iterations, flushing after every reader.read() once
  // the boundary has been crossed. For the no-FINISHED case, we keep
  // a separate list of pre-boundary chunks and emit them at end.
  let seenFinished = false;
  let pendingPostFinished = '';
  const preBoundaryTextChunks: string[] = [];
  let streamEnded = false;

  const flushPending = (): void => {
    if (pendingPostFinished.length > 0) {
      postToBridge(
        { type: 'WEB_LLM_CHUNK', requestId, chunk: pendingPostFinished },
        origin,
      );
      pendingPostFinished = '';
    }
  };

  const processLine = (line: string): void => {
    if (!line.startsWith('data: ')) return;
    const payload = line.slice(6);
    if (payload === '[DONE]') {
      streamEnded = true;
      return;
    }
    let json: Record<string, unknown>;
    try {
      json = JSON.parse(payload) as Record<string, unknown>;
    } catch {
      return;
    }
    if (typeof json.v === 'string' && json.v.length > 0) {
      if (seenFinished) {
        pendingPostFinished += json.v;
      } else {
        const offset = findFinishedOffset(json.v);
        if (offset >= 0) {
          const after = json.v
            .slice(offset + 'FINISHED'.length)
            .replace(/^\s*\n?/, '');
          pendingPostFinished += after;
          seenFinished = true;
        } else {
          preBoundaryTextChunks.push(json.v);
        }
      }
    } else if (json.v && typeof json.v === 'object') {
      // ⑨.2: response container — may carry the assistant message id
      // that the next request needs as `parent_message_id`. The field
      // name varies by server version, so we try a few common shapes.
      const container = json.v as Record<string, unknown>;
      const candidates: unknown[] = [
        container.message_id,
        container.msg_id,
        container.id,
        (container.message as Record<string, unknown> | undefined)?.message_id,
        (container.message as Record<string, unknown> | undefined)?.id,
      ];
      for (const c of candidates) {
        if (typeof c === 'string' && c.length > 0) {
          postToBridge(
            {
              type: 'WEB_LLM_CONVERSATION_UPDATE',
              requestId,
              modelId: request.modelId,
              parentMessageId: c,
            },
            origin,
          );
          break;
        }
      }
    }
  };

  while (!streamEnded) {
    const { done, value } = await dsReader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    while (buffer.includes('\n') && !streamEnded) {
      const lineEnd = buffer.indexOf('\n');
      const line = buffer.slice(0, lineEnd).trim();
      buffer = buffer.slice(lineEnd + 1);
      processLine(line);
    }
    // Flush incremental post-FINISHED text so the user sees it
    // arrive in real time. Before FINISHED, nothing is flushed.
    if (seenFinished) flushPending();
  }

  // ⑨.5: tail bytes that didn't end with a newline. Process them
  // the same way (one last line) and re-enter the loop logic.
  const tail = buffer.trim();
  if (tail.startsWith('data: ')) {
    processLine(tail);
    if (seenFinished) flushPending();
  }

  // ⑨.5: if we never saw a FINISHED marker, treat the entire stream
  // as the answer (non-thinking mode). Emit the pre-boundary chunks
  // as individual CHUNK events so the sidepanel renders them in order.
  if (!seenFinished && preBoundaryTextChunks.length > 0) {
    for (const text of preBoundaryTextChunks) {
      postToBridge({ type: 'WEB_LLM_CHUNK', requestId, chunk: text }, origin);
    }
  }
  postToBridge({ type: 'WEB_LLM_DONE', requestId }, origin);
};
